const crypto = require('crypto');

const item = $input.first();
const request = (item && item.json) || {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};

function getHeader(name) {
  const target = String(name).toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) {
      if (Array.isArray(value)) return typeof value[0] === 'string' ? value[0].trim() : '';
      return typeof value === 'string' ? value.trim() : '';
    }
  }
  return '';
}

function reject(code, message, statusCode = 401) {
  return [{
    json: {
      authenticated: false,
      statusCode,
      code,
      error: message,
    },
  }];
}

const rawSecret = String(($env && $env.DX_WEBHOOK_SECRET) || '').trim();
if (!rawSecret) {
  return reject('WEBHOOK_SECRET_NOT_CONFIGURED', 'DX_WEBHOOK_SECRET is not configured.');
}

const secretBytes = rawSecret.startsWith('whsec_')
  ? Buffer.from(rawSecret.slice(6), 'base64')
  : Buffer.from(rawSecret, 'utf8');

if (!secretBytes || secretBytes.length === 0) {
  return reject('WEBHOOK_SECRET_INVALID', 'DX_WEBHOOK_SECRET is invalid.');
}

const webhookId = getHeader('webhook-id');
const webhookTimestamp = getHeader('webhook-timestamp');
const webhookSignature = getHeader('webhook-signature');

if (!webhookId || !webhookTimestamp || !webhookSignature) {
  return reject('WEBHOOK_HEADERS_MISSING', 'Missing webhook-id, webhook-timestamp, or webhook-signature header.');
}

if (!/^\d{1,12}$/.test(webhookTimestamp)) {
  return reject('WEBHOOK_TIMESTAMP_INVALID', 'Invalid webhook-timestamp header.');
}

const tsSec = Number(webhookTimestamp);
const nowSec = Math.floor(Date.now() / 1000);
if (!Number.isSafeInteger(tsSec) || tsSec <= 0 || Math.abs(nowSec - tsSec) > 300) {
  return reject('WEBHOOK_TIMESTAMP_EXPIRED', 'Webhook timestamp is outside the 300s replay window.');
}

let rawBody = '';
const binaryEntry = item && item.binary && item.binary.data;
const hasInlineBinary = Boolean(binaryEntry && typeof binaryEntry.data === 'string' && binaryEntry.data.length > 0 && !binaryEntry.id);
if (typeof request.rawBody === 'string') {
  rawBody = request.rawBody;
} else if (Buffer.isBuffer(request.rawBody)) {
  rawBody = request.rawBody.toString('utf8');
} else if (hasInlineBinary) {
  rawBody = Buffer.from(binaryEntry.data, 'base64').toString('utf8');
} else if (typeof request.body === 'string') {
  rawBody = request.body;
} else if (request.body !== undefined) {
  rawBody = JSON.stringify(request.body);
}

const signedPayload = webhookId + '.' + webhookTimestamp + '.' + rawBody;
const expectedSig = crypto.createHmac('sha256', secretBytes).update(signedPayload, 'utf8').digest('base64');
const expectedBuf = Buffer.from(expectedSig, 'utf8');

const tokens = webhookSignature.split(/\s+/).filter(Boolean);
let signatureMatched = false;
for (const token of tokens) {
  if (!token.startsWith('v1,')) continue;
  const candidate = token.slice(3);
  if (!candidate) continue;
  const candidateBuf = Buffer.from(candidate, 'utf8');
  if (candidateBuf.length === expectedBuf.length && crypto.timingSafeEqual(candidateBuf, expectedBuf)) {
    signatureMatched = true;
  }
}

if (!signatureMatched) {
  return reject('WEBHOOK_SIGNATURE_INVALID', 'Standard Webhooks v1 HMAC-SHA256 verification failed.');
}

let parsedBody = request.body;
if (typeof parsedBody === 'string') {
  try {
    parsedBody = JSON.parse(parsedBody);
  } catch {
    return reject('WEBHOOK_BODY_INVALID', 'Webhook payload must be valid JSON.', 400);
  }
} else if (parsedBody === undefined && rawBody) {
  try {
    parsedBody = JSON.parse(rawBody);
  } catch {
    return reject('WEBHOOK_BODY_INVALID', 'Webhook payload must be valid JSON.', 400);
  }
}

if (!parsedBody || typeof parsedBody !== 'object' || Array.isArray(parsedBody)) {
  return reject('WEBHOOK_BODY_INVALID', 'Webhook payload must be a JSON object.', 400);
}

return [{
  json: {
    authenticated: true,
    webhookId,
    webhookTimestamp: tsSec,
    body: parsedBody,
  },
}];

const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' && !Array.isArray(input.body) ? input.body : {};
const data = body.data && typeof body.data === 'object' && !Array.isArray(body.data) ? body.data : {};

const eventId = String(body.id || body.eventId || input.webhookId || '').trim();
const rawType = String(body.type || body.eventType || 'epod.captured').trim();
const eventType = rawType.replace(/^latticedx\./i, '').toLowerCase();
const organizationId = String(data.organizationId || body.organizationId || body.organizationid || '').trim();

const SIGNABLE_COLLECTIONS = new Set([
  'latticeRequests',
  'latticeOrders',
  'latticeServiceTickets',
  'latticeAssets',
  'latticeParaDocuments',
  'latticeIncidentCases',
]);

let targetCollection = String(data.targetCollection || data.collection || body.targetCollection || body.collection || '').trim();
let rawRecordId = data.targetRecordId ?? data.recordId ?? body.targetRecordId ?? body.recordId;

if (!targetCollection) {
  if (data.orderId ?? body.orderId) {
    targetCollection = 'latticeOrders';
    rawRecordId = rawRecordId ?? data.orderId ?? body.orderId;
  } else if (data.requestId ?? body.requestId) {
    targetCollection = 'latticeRequests';
    rawRecordId = rawRecordId ?? data.requestId ?? body.requestId;
  } else if (data.ticketId ?? body.ticketId) {
    targetCollection = 'latticeServiceTickets';
    rawRecordId = rawRecordId ?? data.ticketId ?? body.ticketId;
  } else if (data.caseId ?? body.caseId) {
    targetCollection = 'latticeIncidentCases';
    rawRecordId = rawRecordId ?? data.caseId ?? body.caseId;
  } else if (data.assetId ?? body.assetId) {
    targetCollection = 'latticeAssets';
    rawRecordId = rawRecordId ?? data.assetId ?? body.assetId;
  } else if (data.documentId ?? body.documentId) {
    targetCollection = 'latticeParaDocuments';
    rawRecordId = rawRecordId ?? data.documentId ?? body.documentId;
  }
}

const targetRecordId = Number(rawRecordId);
const epodUid = String(data.epodUid || body.epodUid || '').trim() || null;
const trackingCode = String(data.trackingCode || body.trackingCode || '').trim() || null;
const voucherCode = String(data.voucherCode || data.orderCode || data.code || body.voucherCode || '').trim() || null;
const partnerCode = String(data.partnerCode || data.partnerId || body.partnerCode || 'partner-gateway').trim().slice(0, 64);

if (!organizationId || !SIGNABLE_COLLECTIONS.has(targetCollection) || !Number.isInteger(targetRecordId) || targetRecordId <= 0) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      eventId,
      eventType,
      reason: 'ATTESTATION_TARGET_INVALID',
    },
  }];
}

const parts = ['n8n partner sync attestation [' + eventType + ']', 'partner=' + partnerCode];
if (trackingCode) parts.push('trk=' + trackingCode);
if (epodUid) parts.push('epod=' + epodUid);
if (voucherCode) parts.push('doc=' + voucherCode);
if (eventId) parts.push('evt=' + eventId);
const reason = parts.join(' ').slice(0, 255);

return [{
  json: {
    valid: true,
    eventId,
    eventType,
    organizationId,
    targetCollection,
    targetRecordId,
    epodUid,
    trackingCode,
    voucherCode,
    partnerCode,
    signDocumentPayload: {
      organizationId,
      targetCollection,
      targetRecordId,
      reason,
    },
  },
}];
